SELECT customer_id, total_spent
FROM CustomerTotals
WHERE total_spent > (
  SELECT AVG(total_spent)
  FROM CustomerTotals
);

SELECT customer_id, total_spent
FROM CustomerTotals
WHERE AVG(total_spent) > total_spent;

CREATE VIEW HighSpenders AS
SELECT customer_id, total_spent
FROM CustomerTotals;
